INSERT INTO DimAccount (SK_AccountID, AccountID, SK_BrokerID, SK_CustomerID, Status, AccountDesc, TaxStatus, IsCurrent, BatchID, EffectiveDate, EndDate) WITH Accounts AS (SELECT TRY_CAST(Acc.CA_ID AS INT) AS AccountID, Br.SK_BrokerID AS SK_BrokerID, DimC.SK_CustomerID AS SK_CustomerID, Acc.Customer_Id AS Customer_Id, Acc.CA_NAME AS AccountDesc, COALESCE(TRY_CAST(Acc.CA_TAX_ST AS INT), 0) AS TaxStatus, Act.ActionType AS ActionType, CAST(LEFT(Act.ActionTS, 10) AS DATE) AS ActionTS FROM Source.CustomerXML AS C INNER JOIN Source.ActionXML AS Act ON C.Action_Id = Act.Action_Id INNER JOIN Source.AccountXML AS Acc ON C.Customer_Id = Acc.Customer_Id INNER JOIN DimBroker AS Br ON TRY_CAST(Acc.CA_B_ID AS INT) = Br.BrokerID INNER JOIN DimCustomer AS DimC ON C.C_ID = DimC.CustomerID WHERE TRY_CAST(Act.ActionTS AS TIMESTAMP) >= DimC.EffectiveDate AND TRY_CAST(Act.ActionTS AS TIMESTAMP) <= DimC.EndDate), AccountsNewAndAddAcct AS (SELECT *, 'ACTIVE' AS Status FROM Accounts WHERE ActionType IN ('NEW', 'ADDACCT')), AccountsUpd AS (SELECT * FROM Accounts WHERE ActionType = 'UPDACCT'), AccountsCloseAcct AS (SELECT Acc.CA_ID AS AccountID, TRY_CAST(Act.ActionTS AS TIMESTAMP) AS ActionTS FROM Source.AccountXML AS Acc INNER JOIN Source.CustomerXML AS C ON C.Customer_Id = Acc.Customer_Id INNER JOIN Source.ActionXML AS Act ON C.Action_Id = Act.Action_Id WHERE Act.ActionType = 'CLOSEACCT'), AccountsNewAndAddAcctAndUpd AS (SELECT AccountID, SK_BrokerID, SK_CustomerID, CAST('Active' AS TEXT) AS Status, AccountDesc, TaxStatus, ActionTS, ActionType FROM AccountsNewAndAddAcct UNION ALL SELECT UpdAcct.AccountID, COALESCE(UpdAcct.SK_BrokerID, NewAcct.SK_BrokerID) AS SK_BrokerID, COALESCE(UpdAcct.SK_CustomerID, NewAcct.SK_CustomerID) AS SK_CustomerID, NewAcct.Status AS Status, COALESCE(UpdAcct.AccountDesc, NewAcct.AccountDesc) AS AccountDesc, COALESCE(UpdAcct.TaxStatus, NewAcct.TaxStatus) AS TaxStatus, UpdAcct.ActionTS, UpdAcct.ActionType FROM AccountsNewAndAddAcct AS NewAcct INNER JOIN AccountsUpd AS UpdAcct ON NewAcct.AccountID = UpdAcct.AccountID), AccountsFinal AS (SELECT * FROM AccountsNewAndAddAcctAndUpd UNION ALL SELECT AcctNewUpd.AccountID, SK_BrokerID, SK_CustomerID, 'INACTIVE' AS Status, AccountDesc, TaxStatus, AcctNewUpd.ActionTS, 'CLOSEACCT' AS ActionType FROM AccountsNewAndAddAcctAndUpd AS AcctNewUpd INNER JOIN AccountsCloseAcct AS AcctClose ON AcctNewUpd.AccountID = AcctClose.AccountID INNER JOIN (SELECT AccountID, MAX(ActionTS) AS ActionTSLatestAccount FROM AccountsNewAndAddAcctAndUpd GROUP BY AccountID) AS LastAcct ON AcctNewUpd.AccountID = LastAcct.AccountID AND AcctNewUpd.ActionTS = LastAcct.ActionTSLatestAccount) SELECT CAST(CAST(AccountID AS INT) * 1000 + ROW_NUMBER() OVER (PARTITION BY AccountID ORDER BY ActionTS) AS INT) AS SK_AccountID, CAST(AccountID AS INT) AS AccountID, CAST(SK_BrokerID AS INT) AS SK_BrokerID, CAST(SK_CustomerID AS INT) AS SK_CustomerID, CAST(Status AS TEXT) AS Status, CAST(AccountDesc AS TEXT) AS AccountDesc, CAST(TaxStatus AS INT) AS TaxStatus, CAST(CASE WHEN ROW_NUMBER() OVER (PARTITION BY AccountID ORDER BY ActionTS DESC) = 1 THEN TRUE ELSE FALSE END AS BOOLEAN) AS IsCurrent, CAST(1 AS INT) AS BatchID, CAST(ActionTS AS DATE) AS EffectiveDate, CAST(COALESCE(CAST(LEAD(ActionTS) OVER (PARTITION BY AccountID ORDER BY ActionTS) AS DATE), CAST('9999-12-31' AS DATE)) AS DATE) AS EndDate FROM AccountsFinal ORDER BY AccountID, ActionTS ASC;
